def parse_jsonl(blob: str) -> list[dict]:
    rows = []
    for i, line in enumerate(blob.splitlines(), 1):
        line = line.strip()
        if not line:
            continue
        rows.append(json.loads(line))
    return rows


def main() -> None:
    existing = []
    if CORPUS.is_file():
        for line in CORPUS.read_text(encoding="utf-8").splitlines():
            if line.strip():
                existing.append(json.loads(line))
    by_id = {r["id"]: r for r in existing}

    added = 0
    for batch_name, blob in (
        ("guidance_hard", GUIDANCE_HARD),
        ("adversarial", ADVERSARIAL),
        ("semantic_hard", SEMANTIC_HARD),
    ):
        batch = parse_jsonl(blob)
        print(f"{batch_name}: {len(batch)} rows")
        for r in batch:
            if r["id"] in by_id:
                continue
            by_id[r["id"]] = r
            added += 1

    rows = list(by_id.values())
    # Stable-ish order: original-ish then by id
    rows.sort(key=lambda r: r["id"])
    CORPUS.write_text(
        "\n".join(json.dumps(r, ensure_ascii=False) for r in rows) + "\n",
        encoding="utf-8",
    )
    print(f"wrote {CORPUS} total={len(rows)} newly_added={added}")


if __name__ == "__main__":
    main()
